begin;
do $$
declare own uuid; guest uuid; g uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); b uuid; b2 uuid; revision integer; sid uuid; receipt text; state jsonb; original_payments jsonb;
begin
 select id into own from auth.users where not coalesce(is_anonymous,false) and email_confirmed_at is not null order by created_at limit 1;
 select id into guest from auth.users where not coalesce(is_anonymous,false) and email_confirmed_at is not null and id<>own order by created_at limit 1;
 if guest is null then raise exception 'two confirmed fixture accounts required'; end if;
 perform set_config('request.jwt.claim.sub',own::text,true);
 insert into public.travel_groups(id,owner_id,name) values(g,own,'Temporary batch test');
 insert into public.trips(id,group_id,organizer_id,name) values(t,g,own,'Temporary batch test');
 insert into public.trip_access(trip_id,profile_id,role,granted_by) values(t,own,'organizer',own),(t,guest,'participant',own);
 insert into public.group_members(id,group_id,display_name,created_by) values(m,g,'Guest fixture',own);
 insert into public.trip_participants(trip_id,member_id,local_source_id) values(t,m,'guest');
 insert into public.member_profile_links(member_id,profile_id,status,authorized_by) values(m,guest,'active',own);
 original_payments:=jsonb_build_array(jsonb_build_object('id','old-payment','amountCents',12345));
 insert into public.trip_snapshots(trip_id,payload,revision,updated_by) values(t,jsonb_build_object('trip',jsonb_build_object('id',t),'shoppingYear',2026,'shoppingItems',jsonb_build_array(jsonb_build_object('id','a','year',2026,'name','Açúcar','quantity',1,'unitPriceCents',500,'actualTotalCents',500,'purchased',false),jsonb_build_object('id','b','year',2026,'name','Arroz','quantity',1,'unitPriceCents',1000,'actualTotalCents',1000,'purchased',false),jsonb_build_object('id','c','year',2026,'name','Sal','quantity',1,'unitPriceCents',300,'actualTotalCents',300,'purchased',false)),'payments',original_payments,'expenses','[]'::jsonb),1,own);
 perform set_config('request.jwt.claim.sub',guest::text,true);
 b:=public.start_market_purchase(t);
 if public.start_market_purchase(t)<>b then raise exception 'draft not resumed'; end if;
 revision:=public.save_market_purchase_item(b,'{"id":"a","source_item_id":"a","name":"Açúcar","quantity":2,"unit":"kg","total_cents":1200,"picked":true}',1);
 begin perform public.save_market_purchase_item(b,'{"id":"b","source_item_id":"b","name":"Arroz","quantity":1,"total_cents":1000,"picked":true}',1); raise exception 'stale revision accepted'; exception when others then if sqlerrm='stale revision accepted' then raise; end if; end;
 revision:=public.save_market_purchase_item(b,'{"id":"b","source_item_id":"b","name":"Arroz","quantity":1,"total_cents":1100,"picked":true}',revision);
 revision:=public.save_market_purchase_item(b,'{"id":"c","source_item_id":"c","name":"Sal","quantity":1,"total_cents":300,"picked":false}',revision);
 state:=public.get_market_purchase_workspace(t);
 if jsonb_array_length(state->'batches'->0->'items')<>3 then raise exception 'draft items missing on reload'; end if;
 if (select count(*) from public.shopping_purchase_submissions where trip_id=t)<>0 then raise exception 'draft affected official purchases'; end if;
 begin perform public.finalize_market_purchase(b,revision,'Mercado teste',current_date,'personal',2400,null); raise exception 'mismatched total accepted'; exception when others then if sqlerrm='mismatched total accepted' then raise; end if; end;
 perform public.finalize_market_purchase(b,revision,'Mercado teste',current_date,'personal',2300,null);
 if (select status from public.shopping_purchase_batches where id=b)<>'submitted' then raise exception 'guest purchase not pending'; end if;
 if (select count(*) from public.shopping_purchase_submissions where batch_id=b)<>2 then raise exception 'unpicked item submitted'; end if;
 if jsonb_array_length(public.get_market_purchase_workspace(t)->'submissions')<>0 then raise exception 'batch lines duplicated in legacy history'; end if;
 if (select payload->'shoppingItems'->0->>'purchased' from public.trip_snapshots where trip_id=t)<>'false' then raise exception 'guest changed costs before approval'; end if;
 perform set_config('request.jwt.claim.sub',own::text,true);
 select id into sid from public.shopping_purchase_submissions where batch_id=b limit 1;
 begin perform public.review_shopping_purchase(sid,true); raise exception 'individual batch approval allowed'; exception when others then if sqlerrm='individual batch approval allowed' then raise; end if; end;
 perform public.review_market_purchase(b,true);
 if (select payload->'shoppingItems'->0->>'actualTotalCents' from public.trip_snapshots where trip_id=t)<>'1200' then raise exception 'item A price not applied'; end if;
 if (select payload->'shoppingItems'->2->>'purchased' from public.trip_snapshots where trip_id=t)<>'false' then raise exception 'unpicked item marked purchased'; end if;
 begin perform public.review_market_purchase(b,true); raise exception 'double approval allowed'; exception when others then if sqlerrm='double approval allowed' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',guest::text,true);
 receipt:=t::text||'/'||guest::text||'/'||gen_random_uuid()::text||'.jpg';
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('shopping-receipts',receipt,guest::text,'{"mimetype":"image/jpeg","size":10}');
 perform public.attach_market_purchase_receipt(b,receipt);
 if (select count(*) from public.shopping_purchase_submissions where batch_id=b and receipt_path=receipt)<>2 then raise exception 'receipt not shared across purchased items'; end if;
 if not public.shopping_receipt_permission(receipt,false) then raise exception 'author cannot read receipt'; end if;
 perform set_config('request.jwt.claim.sub',own::text,true);
 if not public.shopping_receipt_permission(receipt,false) then raise exception 'organizer cannot read receipt'; end if;
 b2:=public.start_market_purchase(t);
 revision:=public.save_market_purchase_item(b2,'{"id":"extra","name":"Gelo","quantity":1,"total_cents":1500,"picked":true}',1);
 perform set_config('request.jwt.claim.sub',guest::text,true);
 begin perform public.save_market_purchase_item(b2,'{"id":"bad","name":"Wrong user","quantity":1,"total_cents":1,"picked":true}',revision); raise exception 'another account edited draft'; exception when others then if sqlerrm='another account edited draft' then raise; end if; end;
 if exists(select 1 from jsonb_array_elements(public.get_market_purchase_workspace(t)->'batches') x where x->>'id'=b2::text) then raise exception 'another account saw private draft'; end if;
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.finalize_market_purchase(b2,revision,'Outra compra',current_date,'fund',1500,null);
 if (select status from public.shopping_purchase_batches where id=b2)<>'confirmed' then raise exception 'administrator checkout not confirmed'; end if;
 if (select payload->'payments' from public.trip_snapshots where trip_id=t)<>original_payments then raise exception 'payments changed'; end if;
 if has_function_privilege('authenticated','public.review_shopping_purchase_item(uuid,boolean)','execute') or has_function_privilege('anon','public.start_market_purchase(uuid)','execute') then raise exception 'internal function exposed'; end if;
end $$;
rollback;
select 'PASS: draft resumes online, revision conflicts blocked, checkout totals reconciled, unpicked items pending, batch approval atomic and single-use, one late receipt shared, account isolation, administrator checkout and payments preserved; all fixtures rolled back' as result;
